import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.Bbwa0s72.js";const f=JSON.parse('{"title":"0002 — Artifact URLs are credential-free persisted state","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0002-artifact-urls-are-credential-free-state.md","filePath":"spec/decisions/0002-artifact-urls-are-credential-free-state.md"}'),n={name:"spec/decisions/0002-artifact-urls-are-credential-free-state.md"};function s(o,e,c,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_0002-—-artifact-urls-are-credential-free-persisted-state" tabindex="-1">0002 — Artifact URLs are credential-free persisted state <a class="header-anchor" href="#_0002-—-artifact-urls-are-credential-free-persisted-state" aria-label="Permalink to &quot;0002 — Artifact URLs are credential-free persisted state&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-07-29</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Artifact-backed Forms expose <code>artifact_url</code> as a nonsensitive provider attribute and retain it in Terraform/OpenTofu state. The general HTTPS grammar used by OIDC redirect URIs permits query and fragment components. Reusing that grammar for artifact fetching allowed signed or token-bearing query material to enter nonsensitive state.</p><p>Artifact bytes are already bound by SHA-256. Fetch authorization belongs to the host and does not need to travel in portable desired state.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Artifact URLs use a distinct credential-free HTTPS grammar. It accepts an absolute HTTPS URL with a dotted hostname, optional port, and optional path, and rejects userinfo, query, and fragment. Catalog JSON Schema, provider schema validation, runtime conversion, conformance fixtures, examples, and resource documentation derive from that same grammar.</p><p>The general HTTPS grammar remains available to redirect URI declarations and retains its existing acceptance surface.</p><p>Tightening an existing desired schema is a breaking Form change. The six artifact-backed candidates therefore advance to new majors:</p><ul><li><code>EdgeWorker@3.0.0</code></li><li><code>ComputeInstance@2.0.0</code></li><li><code>StaticSite@2.0.0</code></li><li><code>Workflow@2.0.0</code></li><li><code>StatefulEntity@3.0.0</code></li><li><code>ModelEndpoint@3.0.0</code></li></ul><p>Earlier release-source identities remain unchanged.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Artifact fetch credentials stay behind the host credential boundary.</li><li>Nonsensitive provider state cannot retain URL userinfo, query, or fragment.</li><li>Each artifact-backed package carries explicit negative fixtures for all three forbidden URL components.</li><li>Provider <code>v1.0.0</code>, Form versions, and admission generation remain independent.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Mark <code>artifact_url</code> sensitive while retaining credential-bearing URLs.</strong> Rejected because sensitive state still stores the value and portable desired state would still cross the host credential boundary.</li><li><strong>Tighten the shared HTTPS grammar.</strong> Rejected because the redirect-URI contract is a separate surface and narrowing it is outside this decision.</li><li><strong>Rewrite the existing Form versions.</strong> Rejected because release-source identities are immutable and the constraint is a SemVer-major change.</li></ul>',15)])])}const m=t(n,[["render",s]]);export{f as __pageData,m as default};
